CREATE TABLE metadata_user_preferences (tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,locale VARCHAR(2) NULL,time_zone VARCHAR(100) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(tenant_id,user_id),CONSTRAINT metadata_user_locale CHECK(locale IS NULL OR locale IN('pl','en')),CONSTRAINT fk_metadata_preferences_membership FOREIGN KEY(tenant_id,user_id) REFERENCES tenant_memberships(tenant_id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
